{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title_h1",
        "summary_card",
        "section_h2",
        "visit_dist_h3",
        "visit_dist_intro_text",
        "visit_distribution_table",
        "key_metrics_h3",
        "key_metrics_card"
      ]
    },
    "title_h1": {
      "type": "Text",
      "props": {
        "text": "Website Traffic Summary",
        "variant": "h1"
      },
      "children": []
    },
    "summary_card": {
      "type": "Card",
      "props": {},
      "children": [
        "summary_stack"
      ]
    },
    "summary_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "summary_text_1",
        "summary_text_2"
      ]
    },
    "summary_text_1": {
      "type": "Text",
      "props": {
        "text": "This report analyzes the provided website traffic data for three key pages, totaling 9,000 visits."
      },
      "children": []
    },
    "summary_text_2": {
      "type": "Text",
      "props": {
        "text": "It highlights the distribution of visits across pages and identifies the page with the highest bounce rate."
      },
      "children": []
    },
    "section_h2": {
      "type": "Text",
      "props": {
        "text": "Page Performance Breakdown",
        "variant": "h2"
      },
      "children": []
    },
    "visit_dist_h3": {
      "type": "Text",
      "props": {
        "text": "Visit Distribution by Page",
        "variant": "h3"
      },
      "children": []
    },
    "visit_dist_intro_text": {
      "type": "Text",
      "props": {
        "text": "The following shows the proportion of total visits each page received."
      },
      "children": []
    },
    "visit_distribution_table": {
      "type": "Table",
      "props": {
        "title": "Website Page Visit Distribution",
        "columns": [
          {
            "key": "Page",
            "label": "Page"
          },
          {
            "key": "Visits Percentage",
            "label": "Visits Percentage"
          }
        ],
        "rows": [
          {
            "Page": "/home",
            "Visits Percentage": 55.6
          },
          {
            "Page": "/products",
            "Visits Percentage": 33.3
          },
          {
            "Page": "/contact",
            "Visits Percentage": 11.1
          }
        ],
        "domain": "generic",
        "preferredPresentation": "table"
      },
      "children": []
    },
    "key_metrics_h3": {
      "type": "Text",
      "props": {
        "text": "Key Metrics",
        "variant": "h3"
      },
      "children": []
    },
    "key_metrics_card": {
      "type": "Card",
      "props": {},
      "children": [
        "key_metrics_stack"
      ]
    },
    "key_metrics_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "bounce_rate_text_1",
        "bounce_rate_text_2"
      ]
    },
    "bounce_rate_text_1": {
      "type": "Text",
      "props": {
        "text": "The page with the highest bounce rate is /products at 45%."
      },
      "children": []
    },
    "bounce_rate_text_2": {
      "type": "Text",
      "props": {
        "text": "This indicates that nearly half of the visitors to the products page leave after viewing only that page."
      },
      "children": []
    }
  }
}
